import{_ as e,o as t,c as a,a6 as o}from"./chunks/framework.BlDtR6jM.js";const u=JSON.parse('{"title":"音乐网站及资源","description":"","frontmatter":{"readingTime":"5 min read"},"headers":[],"relativePath":"游戏设计/音乐/音乐网站/音乐网站.md","filePath":"游戏设计/音乐/音乐网站/音乐网站.md"}'),i={name:"游戏设计/音乐/音乐网站/音乐网站.md"};function n(l,r,s,h,g,b){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="音乐网站及资源" tabindex="-1">音乐网站及资源 <a class="header-anchor" href="#音乐网站及资源" aria-label="Permalink to &quot;音乐网站及资源&quot;">​</a></h1><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h3><ul><li><a href="https://blips.fm/" target="_blank" rel="noreferrer">Download Royalty-Free Music For Games</a></li><li><a href="https://blog.blips.fm/articles/adaptive-music-in-video-games-what-it-is-and-how-it-works" target="_blank" rel="noreferrer">Adaptive music in video games</a></li><li><a href="https://blog.blips.fm/articles/blips-is-now-offering-free-game-music-packs" target="_blank" rel="noreferrer">Blips 现在提供免费游戏音乐包</a></li></ul><h4 id="_1-国外核心平台" tabindex="-1">1. 国外核心平台 <a class="header-anchor" href="#_1-国外核心平台" aria-label="Permalink to &quot;1. 国外核心平台&quot;">​</a></h4><ul><li><strong>OC ReMix (OverClocked ReMix)</strong><br> 全球最权威的游戏音乐重混社区，收录数千首高质量非官方重混作品，风格从电子到交响全覆盖，可免费下载与交流。<br> 网址：<a href="https://ocremix.org/" target="_blank" rel="noreferrer">https://ocremix.org/</a></li><li><strong>VGMdb</strong><br> 游戏音乐百科全书，收录几乎所有游戏OST、专辑、作曲家信息，是查资料与找正版/资源的核心站。<br> 网址：<a href="https://vgmdb.net/" target="_blank" rel="noreferrer">https://vgmdb.net/</a></li><li><strong>Newgrounds Audio Portal</strong><br> 老牌独立创作平台，大量独立游戏音乐人、音效师发布原创BGM与音效，适合找小众、实验性作品。<br> 网址：<a href="https://www.newgrounds.com/audio" target="_blank" rel="noreferrer">https://www.newgrounds.com/audio</a></li></ul><h4 id="_2-国内平台" tabindex="-1">2. 国内平台 <a class="header-anchor" href="#_2-国内平台" aria-label="Permalink to &quot;2. 国内平台&quot;">​</a></h4><ul><li><strong>Indienova 独立游戏（音乐板块）</strong><br> 国内独立游戏开发者聚集地，有大量游戏音乐创作心得、教程与作品分享。<br> 网址：<a href="https://indienova.com/" target="_blank" rel="noreferrer">https://indienova.com/</a></li><li><strong>奶牛关（游戏音乐区）</strong><br> 玩家与创作者交流OST、重混、游戏音乐赏析的社区。<br> 网址：<a href="https://cowlevel.net/" target="_blank" rel="noreferrer">https://cowlevel.net/</a></li><li><strong>B站（Bilibili）</strong><br> 大量游戏音乐翻奏、重混、OST合集、编曲教程，关键词：游戏音乐、VGM、编曲教程。</li></ul><hr><h3 id="二、游戏音乐制作教程与学习网站" tabindex="-1">二、游戏音乐制作教程与学习网站 <a class="header-anchor" href="#二、游戏音乐制作教程与学习网站" aria-label="Permalink to &quot;二、游戏音乐制作教程与学习网站&quot;">​</a></h3><h4 id="_1-综合教程平台" tabindex="-1">1. 综合教程平台 <a class="header-anchor" href="#_1-综合教程平台" aria-label="Permalink to &quot;1. 综合教程平台&quot;">​</a></h4><ul><li><strong>YouTube 优质频道（英文为主，可开字幕）</strong><ul><li><strong>8-Bit Music Theory</strong>：游戏音乐理论、经典OST分析、复古风格制作。</li><li><strong>LNA Does Audio Stuff</strong>：Ableton Live 游戏音乐制作、免费音色与模板分享。</li><li><strong>Game Audio Institute</strong>：职业向游戏音频设计、实现、 middleware（Wwise/FMOD）教程。</li><li><strong>Steinberg、Native Instruments 官方频道</strong>：DAW与音源在游戏音乐中的应用教程。</li></ul></li><li><strong>Udemy / Coursera</strong> 搜索关键词：Game Music Composition、Game Audio Design、Interactive Music，有系统课程（付费为主，常打折）。</li><li><strong>GANG (Game Audio Network Guild)</strong><br> 行业组织，提供大量免费讲座、白皮书、行业标准与职业指南。 网址：<a href="https://audiogang.org/" target="_blank" rel="noreferrer">https://audiogang.org/</a></li></ul><h4 id="_2-国内教程与社区" tabindex="-1">2. 国内教程与社区 <a class="header-anchor" href="#_2-国内教程与社区" aria-label="Permalink to &quot;2. 国内教程与社区&quot;">​</a></h4><ul><li><strong>Indienova 游戏音乐教程合集</strong><br> 收录多篇中文自学心得、工具推荐、流程指南，适合新手入门。</li><li><strong>midifan（音频应用）</strong><br> 音频技术社区，有游戏音乐制作、DAW、音源、混音相关教程与讨论。 网址：<a href="https://www.midifan.com/" target="_blank" rel="noreferrer">https://www.midifan.com/</a></li><li><strong>音频应用论坛（AudioApp）</strong><br> 国内老牌音频论坛，游戏音频板块有技术交流、作品展示与资源分享。</li></ul><hr><h3 id="三、游戏音乐素材与工具网站" tabindex="-1">三、游戏音乐素材与工具网站 <a class="header-anchor" href="#三、游戏音乐素材与工具网站" aria-label="Permalink to &quot;三、游戏音乐素材与工具网站&quot;">​</a></h3><h4 id="_1-免版税音乐-音效库" tabindex="-1">1. 免版税音乐/音效库 <a class="header-anchor" href="#_1-免版税音乐-音效库" aria-label="Permalink to &quot;1. 免版税音乐/音效库&quot;">​</a></h4><ul><li><strong>OpenGameArt.org</strong><br> 专注游戏素材，含大量免费/CC0游戏BGM、循环乐段、音效，按风格/场景筛选。<br> 网址：<a href="https://opengameart.org/" target="_blank" rel="noreferrer">https://opengameart.org/</a></li><li><strong>Freesound</strong><br> 全球最大免费音效库，搜索 game、bgm、loop 等关键词，大量CC0素材可商用。<br> 网址：<a href="https://freesound.org/" target="_blank" rel="noreferrer">https://freesound.org/</a></li><li><strong>AudioJungle</strong><br> 海量 royalty-free 音乐与音效，含专门游戏音乐分类，适合快速找成品BGM。<br> 网址：<a href="https://audiojungle.net/" target="_blank" rel="noreferrer">https://audiojungle.net/</a></li><li><strong>GameDev Market</strong><br> 游戏开发者专属素材市场，音乐、音效、配乐包丰富，性价比高。<br> 网址：<a href="https://www.gamedevmarket.net/" target="_blank" rel="noreferrer">https://www.gamedevmarket.net/</a></li><li><strong>Mixkit</strong><br> 免费高质量游戏音效（UI、战斗、环境），可直接商用无需署名。<br> 网址：<a href="https://mixkit.co/" target="_blank" rel="noreferrer">https://mixkit.co/</a></li></ul><h4 id="_2-在线制作工具-新手快速出活" tabindex="-1">2. 在线制作工具（新手快速出活） <a class="header-anchor" href="#_2-在线制作工具-新手快速出活" aria-label="Permalink to &quot;2. 在线制作工具（新手快速出活）&quot;">​</a></h4><ul><li><strong>BeepBox</strong>：在线8-bit/芯片音乐制作，网格编辑，导出WAV/MP3。<br> 网址：<a href="https://www.beepbox.co/" target="_blank" rel="noreferrer">https://www.beepbox.co/</a></li><li><strong>Bosca Ceoil</strong>：极简在线作曲，预制和弦/鼓组，适合快速做复古风循环BGM。<br> 网址：<a href="https://boscaceoil.net/" target="_blank" rel="noreferrer">https://boscaceoil.net/</a></li><li><strong>Suno AI</strong>：AI生成游戏音乐，输入风格/场景描述快速出曲，适合灵感与Demo。<br> 网址：<a href="https://suno.ai/" target="_blank" rel="noreferrer">https://suno.ai/</a></li></ul>',19)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
